{
  "dashboard": {
    "title": "DR 验证概览",
    "panels": [
      {
        "title": "备份验证成功率",
        "type": "stat",
        "targets": [
          { "expr": "sum(rate(backup_validation_success_total[1d])) / sum(rate(backup_validation_attempt_total[1d])) * 100" }
        ]
      },
      {
        "title": "数据一致性检查",
        "type": "stat",
        "targets": [
          { "expr": "data_consistency_check_success" }
        ]
      },
      {
        "title": "RTO 趋势",
        "type": "graph",
        "targets": [
          { "expr": "dr_rto_seconds" }
        ]
      },
      {
        "title": "RPO 趋势",
        "type": "graph",
        "targets": [
          { "expr": "dr_rpo_seconds" }
        ]
      },
      {
        "title": "复制延迟",
        "type": "graph",
        "targets": [
          { "expr": "pg_replication_lag_seconds" }
        ]
      }
    ]
  }
}
